def get_entries(args: TypedArgs) -> list[str]:
    # Read entries from command line or stdin?
    # If reading from stdin, are entries split on nulls or newlines?
    if len(args.entries) > 0:
        entries = args.entries
    else:
        separator = "\0" if args.zero_terminated else "\n"
        entries = sys.stdin.read().rstrip(separator).split(separator)

    # Remove trailing whitespace from all the entries
    return [e.strip() for e in entries]

def fast_float(
    x: str,
    key: Callable[[str], str] = lambda x: x,
    nan: float = float("inf"),
    _uni: Callable[[str, StrOrFloat], StrOrFloat] = unicodedata.numeric,
    _nan_inf: frozenset[str] = NAN_INF,
    _first_char: frozenset[str] = POTENTIAL_FIRST_CHAR,
) -> StrOrFloat:
    if x[0] in _first_char or x.lstrip()[:3] in _nan_inf:
        try:
            ret = float(x)
        except ValueError:
            try:
                return _uni(x, key(x)) if len(x) == 1 else key(x)
            except TypeError:  # pragma: no cover
                return key(x)
        else:
            return nan if ret != ret else ret
    else:
        try:
            return _uni(x, key(x)) if len(x) == 1 else key(x)
        except TypeError:  # pragma: no cover
            return key(x)

