def delimitedList(expr, delim=",", combine=False, *, allowTrailingDelim=False):
    dlName = "{expr} [{delim} {expr}]...{end}".format(
        expr=str(expr),
        delim=str(delim),
        end=" [{}]".format(str(delim)) if allowTrailingDelim else "",
