def comment(self, comment: str) -> Item:
    if "\n" in comment or "\r" in comment:
        raise ValueError("Comment cannot contain line breaks")
    if not comment.strip().startswith("#"):
        comment = "# " + comment

    self._trivia.comment_ws = " "
    self._trivia.comment = comment

    return self

def item(value: Any, _parent: Item | None = None, _sort_keys: bool = False) -> Item:

    from tomlkit.container import Container

    if isinstance(value, Item):
        return value

    if isinstance(value, bool):
        return Bool(value, Trivia())
    elif isinstance(value, int):
        return Integer(value, Trivia(), str(value))
    elif isinstance(value, float):
        return Float(value, Trivia(), str(value))
    elif isinstance(value, dict):
        table_constructor = (
            InlineTable if isinstance(_parent, (Array, InlineTable)) else Table
        )
        val = table_constructor(Container(), Trivia(), False)
        for k, v in sorted(
            value.items(),
            key=lambda i: (isinstance(i[1], dict), i[0]) if _sort_keys else 1,
        ):
            val[k] = item(v, _parent=val, _sort_keys=_sort_keys)

        return val
    elif isinstance(value, (list, tuple)):
        a: AoT | Array
        if (
            value
            and all(isinstance(v, dict) for v in value)
            and (_parent is None or isinstance(_parent, Table))
        ):
            a = AoT([])
            table_constructor = Table
        else:
            a = Array([], Trivia())
            table_constructor = InlineTable

        if table_constructor is Table:
            # AoT tables render as ``[[table]]`` headers, so dict-valued keys
            # must come last to avoid them capturing the following keys.
            def _sort_key(i: tuple[Any, Any]) -> Any:
                return (isinstance(i[1], dict), i[0] if _sort_keys else 1)
        else:
            # Inline tables cannot capture, so there is no need to put
            # dict-valued keys last: preserve insertion order, or sort purely
            # by key when explicitly requested. See #546.
            def _sort_key(i: tuple[Any, Any]) -> Any:
                return i[0] if _sort_keys else 1

        for v in value:
            if isinstance(v, dict):
                table = table_constructor(Container(), Trivia(), True)

                for k, _v in sorted(v.items(), key=_sort_key):
                    i = item(_v, _parent=table, _sort_keys=_sort_keys)
                    if isinstance(table, InlineTable):
                        i.trivia.trail = ""

                    table[k] = i

                v = table

            a.append(v)

        return a
    elif isinstance(value, str):
        return String.from_raw(value)
    elif isinstance(value, datetime):
        return DateTime(
            value.year,
            value.month,
            value.day,
            value.hour,
            value.minute,
            value.second,
            value.microsecond,
            value.tzinfo,
            Trivia(),
            value.isoformat().replace("+00:00", "Z"),
            fold=value.fold,
        )
    elif isinstance(value, date):
        return Date(value.year, value.month, value.day, Trivia(), value.isoformat())
    elif isinstance(value, time):
        return Time(
            value.hour,
            value.minute,
            value.second,
            value.microsecond,
            value.tzinfo,
            Trivia(),
            _format_time(value),
            fold=value.fold,
        )
    else:
        for encoder in CUSTOM_ENCODERS:
            try:
                # Check if encoder accepts keyword arguments for backward compatibility
                sig = inspect.signature(encoder)
                has_kwargs = any(
                    p.kind == p.VAR_KEYWORD for p in sig.parameters.values()
                )
                first_parameter = next(iter(sig.parameters.values()), None)
                bound_name = (
                    first_parameter.name
                    if first_parameter is not None
                    and first_parameter.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
                    else None
                )
                context = {"_parent": _parent, "_sort_keys": _sort_keys}
                kwargs = {
                    name: argument
                    for name, argument in context.items()
                    if name != bound_name
                    and (
                        has_kwargs
                        or (
                            name in sig.parameters
                            and sig.parameters[name].kind
                            in (
                                inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                inspect.Parameter.KEYWORD_ONLY,
                            )
                        )
                    )
                }
                rv = encoder(value, **kwargs)
            except ConvertError:
                pass
            else:
                if not isinstance(rv, Item):
                    raise ConvertError(
                        f"Custom encoder is expected to return an instance of Item, got {type(rv)}"
                    )
                return rv

    raise ConvertError(f"Unable to convert an object of {type(value)} to a TOML item")

