            elif c == "[":
                # Found a table, delegate to the calling function.
                return
            else:
                # Beginning of a KV pair.
                # Return to beginning of whitespace so it gets included
                # as indentation for the KV about to be parsed.
                state.restore = True
                break

    return self._parse_key_value(True)

