                        else:
                            self._raw_append(key, item)

                        if validate:
                            self._validate_out_of_order_table(key)

                        return self

                    # Create a new element to replace the old one
                    current = copy.deepcopy(current)
                    for k, v in item.value.body:
                        current.append(k, v)
                    self._body[
                        (
                            current_idx[-1]
                            if isinstance(current_idx, tuple)
                            else current_idx
